def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_opp = history[-1][1]
    last_me = history[-1][0]

    # End-game exploitation logic
    if n >= 95:
        opp_c_total = sum(1 for _, b in history if b == 'C')
        opp_rate = opp_c_total / n
        if opp_rate > 0.7:
            return 'D'
        elif opp_rate < 0.3:
            return 'D' if last_opp == 'C' else 'C'
        else:
            return 'D'

    # Early game tit-for-tat with forgiveness
    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Compute statistics
    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')
    opp_d = n - opp_c
    my_d = n - my_c

    # Detect pure defectors early and punish
    if opp_c <= 2 and n > 10:
        return 'D'

    # If opponent is extremely cooperative, occasionally defect to exploit
    if opp_c / n > 0.85:
        if last_opp == 'C':
            if rng.random() < 0.1:
                return 'D'
            return 'C'
        else:
            return 'D'

    # Recent behavior analysis
    recent_window = min(n, 15)
    recent_hist = history[-recent_window:]
    recent_opp_c = sum(1 for a, b in recent_hist if b == 'C')
    recent_opp_d = recent_window - recent_opp_c

    # Strategy based on recent trends
    if recent_opp_d == 0:
        return 'C'

    if recent_opp_d >= 4:
        # Opponent has been defecting frequently recently
        if last_opp == 'D':
            return 'D'
        else:
            # They just cooperated after a streak of defection? Maybe forgive slightly or stay firm.
            # If we were cooperating during their streak, we might be getting exploited.
            if my_c > opp_c:
                return 'D'
            return 'C' if rng.random() < 0.3 else 'D'

    if recent_opp_d <= 2:
        # Mostly cooperative recently
        if last_opp == 'D':
            # Tit-for-tat response, but with some probability of forgiveness if overall relationship is good
            if opp_c / n > 0.6:
                return 'C' if rng.random() < 0.4 else 'D'
            return 'D'
        else:
            return 'C'

    # Intermediate cases
    if last_opp == 'D':
        if my_c > opp_c + 5:
            # We are being overly nice, start punishing more
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'
    else:
        # Last opp C
        if my_d > opp_d + 5:
            # We have been aggressive, maybe soften up to encourage mutual cooperation
            return 'C'
        return 'C'
